"""Config loader.

Precedence, lowest to highest:
  1. config/base.json
  2. config/<APP_ENV>.json     (APP_ENV defaults to "prod" for local shells)
  3. env vars named APP_<SECTION>__<KEY>

A worker process holds at most db.pool_size + db.overflow open connections.
"""
import json, os, pathlib

ROOT = pathlib.Path(__file__).resolve().parent.parent
DEFAULT_ENV = "prod"


def _merge(dst, src):
    for k, v in src.items():
        if isinstance(v, dict) and isinstance(dst.get(k), dict):
            _merge(dst[k], v)
        else:
            dst[k] = v


def load():
    cfg = json.loads((ROOT / "config" / "base.json").read_text())
    env = os.environ.get("APP_ENV", DEFAULT_ENV)
    path = ROOT / "config" / (env + ".json")
    if path.exists():
        _merge(cfg, json.loads(path.read_text()))
    for name, val in os.environ.items():
        if not name.startswith("APP_") or "__" not in name:
            continue
        section, key = name[4:].split("__", 1)
        section, key = section.lower(), key.lower()
        if section in cfg and key in cfg[section]:
            cfg[section][key] = int(val) if val.lstrip("-").isdigit() else val
    return cfg


if __name__ == "__main__":
    print(json.dumps(load(), indent=2))

