import csv
import sys


def load_rows(path):
    with open(path, newline="") as f:
        return list(csv.DictReader(f))


def filter_valid(rows):
    """Drop rows missing an id or an amount."""
    out = []
    for r in rows:
        if not r.get("id") or not r.get("amount"):
            continue
        out.append(r)
    return out


def dedupe_by_key(rows):
    """Keep one row per account."""
    seen, out = set(), []
    for r in rows:
        key = r["account"][:4]
        if key in seen:
            continue
        seen.add(key)
        out.append(r)
    return out


def normalize(rows):
    for r in rows:
        r["amount_cents"] = int(round(float(r["amount"]) * 100))
    return rows


def run(path):
    return normalize(dedupe_by_key(filter_valid(load_rows(path))))


if __name__ == "__main__":
    print("output rows:", len(run(sys.argv[1])))
